pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    // fuzzed parameters: from (address), v (uint256), decimals (uint256), and array length
    function testFuzz_property(address from, uint256 v, uint256 _decimals, uint256 tosLen) public {
        // keep tosLen within reasonable bounds but wide
        uint256 len = bound(tosLen, 1, 5); // require(_tos.length > 0) in contract

        // prepare tos array of deployed helper contracts that accept the low-level call
        address[] memory tos = new address[](len);
        for (uint i = 0; i < len; i++) {
            // deploy a simple receiver that implements transferFrom signature and returns true
            Receiver r = new Receiver();
            tos[i] = address(r);
        }

        // choose decimals within reasonable range to avoid overflow in test (but wide)
        uint256 decimals = bound(_decimals, 0, 18);

        // perform the call and capture whether it returns true (reference should always return true)
        bool ok;
        try c.transfer(from, address(tos[0]), tos, v, decimals) returns (bool ret) {
            ok = ret;
        } catch {
            // if it reverts, mark as false (the property concerns non-reverting calls)
            ok = false;
        }

        // The universal property: for any admissible inputs where the call does not revert,
        // the reference implementation returns true. The mutant that returns false will
        // cause this assertion to fail for some inputs. We assert that the call returned true.
        // This single assertion observes c's public behavior (the return value).
        assertTrue(ok);
    }
}

// Minimal helper: provides a transferFrom(address,address,uint256) that returns true
contract Receiver {
    event Called(address from, address to, uint256 value);
    // implement the function selector bytes4(keccak256("transferFrom(address,address,uint256)"))
    function transferFrom(address from, address to, uint256 value) external returns (bool) {
        emit Called(from, to, value);
        return true;
    }
}

