    // The adversarial callee will always succeed (returning true) so that reference returns true.
    // We must ensure _tos.length > 0 per contract require. We'll construct an array with at least one entry.
    function testFuzz_property(address from, uint256 v, uint256 _decimals, address toAddr) public {
        // Keep decimals reasonable to avoid overflow in v * 10 ** _decimals
        _decimals = bound(_decimals, 0, 18);
