        address[] memory tos = new address[](1);
        // Use a helper contract that will accept the low-level call and return success
        HelperAccept h = new HelperAccept();
        tos[0] = address(h);

        // Call transfer and capture its boolean result via try/catch to observe actual return (per rules)
        bool ok;
        try c.transfer(from, address(h), tos, v, _decimals) returns (bool ret) {
            ok = ret;
