// Minimal helper that always returns true for the specific selector transferFrom(address,address,uint256)
contract HelperAccept {
    // The low-level call from C uses abi.encodeWithSelector(id, from, _tos[i], _value)
    // We implement a fallback that returns true (encoded as abi.encode(true)) for any call.
    fallback() external payable returns (bytes memory) {
        return abi.encode(true);
    }
    receive() external payable {}
}

